<?php /* av-splash.php — drop-in loading page. Include at the very top of your page, right after <body>. */ ?>
<script>document.documentElement.classList.add('av-loading');</script>
<style>

  @import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Rajdhani:wght@500;600;700&display=swap');
  #av-splash *, #av-splash *::before, #av-splash *::after { margin:0; padding:0; box-sizing:border-box; }

  /* Lock the page + hide everything behind the splash until it finishes */
  html.av-loading, html.av-loading body { overflow:hidden !important; height:100%; }
  html.av-loading body > *:not(#av-splash) { visibility:hidden !important; }

  #av-splash {
    position:fixed; inset:0; z-index:2147483647;
    background:#04060f;
    display:flex; align-items:center; justify-content:center;
    font-family:'Rajdhani',sans-serif;
    overflow:hidden;
    transition:opacity .7s ease;
  }
  #av-splash.av-hide { opacity:0; pointer-events:none; }

  /* ===== Animated aurora background ===== */
  .aurora { position:fixed; inset:0; z-index:0; overflow:hidden; background:#04060f; }
  .aurora span {
    position:absolute; border-radius:50%; filter:blur(70px); opacity:0.55;
    mix-blend-mode:screen;
  }
  .a1 { width:520px; height:520px; background:#d1001f; top:-160px; left:-120px; animation:drift1 9s ease-in-out infinite; }
  .a2 { width:560px; height:560px; background:#0033ff; bottom:-180px; right:-140px; animation:drift2 11s ease-in-out infinite; }
  .a3 { width:360px; height:360px; background:#ff2a4d; bottom:-120px; left:-80px; animation:drift3 13s ease-in-out infinite; }
  .a4 { width:380px; height:380px; background:#1e63ff; top:-100px; right:-90px; animation:drift4 10s ease-in-out infinite; }
  @keyframes drift1 { 0%,100%{transform:translate(0,0) scale(1);} 50%{transform:translate(80px,60px) scale(1.15);} }
  @keyframes drift2 { 0%,100%{transform:translate(0,0) scale(1);} 50%{transform:translate(-70px,-50px) scale(1.1);} }
  @keyframes drift3 { 0%,100%{transform:translate(0,0) scale(1);} 50%{transform:translate(60px,-40px) scale(1.2);} }
  @keyframes drift4 { 0%,100%{transform:translate(0,0) scale(1);} 50%{transform:translate(-50px,70px) scale(1.1);} }

  /* subtle grain/grid overlay */
  .grid {
    position:fixed; inset:0; z-index:1; opacity:0.08;
    background-image:linear-gradient(rgba(255,255,255,.5) 1px, transparent 1px),
                     linear-gradient(90deg, rgba(255,255,255,.5) 1px, transparent 1px);
    background-size:42px 42px;
    mask-image:radial-gradient(circle at center, black 30%, transparent 75%);
    -webkit-mask-image:radial-gradient(circle at center, black 30%, transparent 75%);
  }

  /* ===== Orbiting particles ===== */
  .particles { position:fixed; inset:0; z-index:2; pointer-events:none; }
  .particle { position:absolute; border-radius:50%; opacity:0; animation:rise linear infinite; }
  @keyframes rise {
    0% { transform:translateY(20px) scale(0); opacity:0; }
    12% { opacity:1; }
    88% { opacity:.6; }
    100% { transform:translateY(-110vh) scale(1.4); opacity:0; }
  }

  /* ===== Stage ===== */
  .stage { position:relative; z-index:10; display:flex; flex-direction:column; align-items:center; }

  .logo-zone { position:relative; width:340px; height:340px; display:flex; align-items:center; justify-content:center; }

  /* Rotating dashed orbit rings */
  .orbit {
    position:absolute; border-radius:50%; border:2px dashed rgba(255,255,255,.25);
    opacity:0; 
  }
  .orbit-1 { width:330px; height:330px; animation:spinCW 14s linear infinite, fadeIn .8s 1.3s forwards; }
  .orbit-2 { width:372px; height:372px; border-style:dotted; border-color:rgba(255,90,90,.35); animation:spinCCW 20s linear infinite, fadeIn .8s 1.5s forwards; }
  @keyframes spinCW { to { transform:rotate(360deg); } }
  @keyframes spinCCW { to { transform:rotate(-360deg); } }
  @keyframes fadeIn { to { opacity:1; } }

  /* orbit satellite dots */
  .satellite { position:absolute; width:330px; height:330px; opacity:0; animation:spinCW 14s linear infinite, fadeIn .8s 1.3s forwards; }
  .satellite::before {
    content:''; position:absolute; top:-6px; left:50%; transform:translateX(-50%);
    width:12px; height:12px; border-radius:50%; background:#fff;
    box-shadow:0 0 14px #fff, 0 0 26px #4488ff;
  }
  .satellite-2 { width:372px; height:372px; animation:spinCCW 20s linear infinite, fadeIn .8s 1.5s forwards; }
  .satellite-2::before { background:#ff3b5c; box-shadow:0 0 14px #ff3b5c, 0 0 26px #ff3b5c; }

  /* Conic glow halo */
  .halo {
    position:absolute; width:312px; height:312px; border-radius:50%;
    background:conic-gradient(from 0deg, #d1001f, #ff5a5a, #1e63ff, #0033ff, #d1001f);
    filter:blur(14px); opacity:0; 
    animation:spinCW 4s linear infinite, haloIn .6s 1.1s forwards;
  }
  @keyframes haloIn { to { opacity:.7; } }

  /* Pulse shockwaves */
  .pulse { position:absolute; width:300px; height:300px; border-radius:50%; border:2px solid rgba(255,255,255,.5); opacity:0; }
  .pulse-1 { animation:shock 2.4s 1.6s ease-out infinite; }
  .pulse-2 { animation:shock 2.4s 2.4s ease-out infinite; }
  .pulse-3 { animation:shock 2.4s 3.2s ease-out infinite; }
  @keyframes shock { 0%{transform:scale(.92);opacity:.55;} 100%{transform:scale(1.55);opacity:0;} }

  /* ===== The REAL logo (unchanged image) ===== */
  .logo {
    position:relative; z-index:5; width:280px; height:280px; border-radius:50%;
    object-fit:cover;
    box-shadow:0 0 40px rgba(255,255,255,.25), 0 0 90px rgba(40,80,255,.35);
    opacity:0;
    animation:logoIn 1.1s .5s cubic-bezier(.2,1.3,.4,1) forwards, breathe 3.5s 1.7s ease-in-out infinite;
  }
  @keyframes logoIn {
    0% { opacity:0; transform:rotate(-720deg) scale(.1); filter:blur(8px); }
    60%{ opacity:1; filter:blur(0); }
    100%{ opacity:1; transform:rotate(0deg) scale(1); filter:blur(0); }
  }
  @keyframes breathe {
    0%,100% { transform:scale(1); }
    50% { transform:scale(1.035); }
  }

  /* light sweep over logo */
  .logo-zone .sweep {
    position:absolute; z-index:6; width:280px; height:280px; border-radius:50%;
    overflow:hidden; pointer-events:none; opacity:0; animation:fadeIn .5s 1.7s forwards;
  }
  .logo-zone .sweep::before {
    content:''; position:absolute; top:-50%; left:-120%;
    width:60%; height:200%;
    background:linear-gradient(105deg, transparent, rgba(255,255,255,.55), transparent);
    transform:rotate(20deg);
    animation:sweep 3.5s 2s ease-in-out infinite;
  }
  @keyframes sweep { 0%{left:-120%;} 60%,100%{left:160%;} }

  /* ===== Title ===== */
  .title-wrap { margin-top:38px; text-align:center; opacity:0; animation:upIn .7s 1.8s forwards; }
  @keyframes upIn { from{opacity:0;transform:translateY(24px);} to{opacity:1;transform:translateY(0);} }
  .title {
    font-family:'Bebas Neue',sans-serif; font-weight:700; font-size:48px; letter-spacing:9px;
    background:linear-gradient(90deg,#ff5a5a,#ffffff,#5a8bff);
    -webkit-background-clip:text; background-clip:text; color:transparent;
    text-shadow:0 0 40px rgba(255,255,255,.3);
  }
  .subtitle { font-size:14px; letter-spacing:10px; color:rgba(255,255,255,.55); margin-top:6px; text-transform:uppercase; }

  /* ===== Progress bar ===== */
  .progress { margin-top:42px; width:280px; opacity:0; animation:upIn .6s 2.1s forwards; }
  .progress .row { display:flex; justify-content:space-between; font-size:11px; letter-spacing:3px; color:rgba(255,255,255,.5); text-transform:uppercase; margin-bottom:9px; }
  #pct { color:#fff; font-weight:700; }
  .track { width:100%; height:4px; background:rgba(255,255,255,.08); border-radius:4px; overflow:hidden; position:relative; }
  .bar {
    height:100%; width:0%;
    background:linear-gradient(90deg,#d1001f,#ff5a5a 40%,#5a8bff 60%,#0033ff);
    border-radius:4px; box-shadow:0 0 14px rgba(120,120,255,.7);
    animation:fill 3s 2.3s cubic-bezier(.45,0,.15,1) forwards;
  }
  @keyframes fill { 0%{width:0;} 18%{width:14%;} 38%{width:36%;} 58%{width:60%;} 80%{width:84%;} 100%{width:100%;} }
  .bar::after {
    content:''; position:absolute; top:0; left:-30%; width:30%; height:100%;
    background:linear-gradient(90deg,transparent,rgba(255,255,255,.7),transparent);
    animation:shimmer 1.4s 2.3s linear infinite;
  }
  @keyframes shimmer { to { left:120%; } }

</style>

<div id="av-splash">
<div class="aurora">
  <span class="a1"></span><span class="a2"></span><span class="a3"></span><span class="a4"></span>
</div>
<div class="particles" id="particles"></div>

<div class="stage">
  <div class="logo-zone">
    <div class="pulse pulse-1"></div>
    <div class="pulse pulse-2"></div>
    <div class="pulse pulse-3"></div>
    <div class="halo"></div>
    <div class="orbit orbit-2"></div>
    <div class="orbit orbit-1"></div>
    <div class="satellite"></div>
    <div class="satellite satellite-2"></div>
    <img class="logo" src="data:image/jpeg;base64," alt="Aishwarya Arts & Sports Club" />
    <div class="sweep"></div>
  </div>

  <div class="title-wrap">
    <div class="title">AISHWARYA</div>
    <div class="subtitle">Vettikkattiri</div>
  </div>

  <div class="progress">
    <div class="row"><span>Loading</span><span id="pct">0%</span></div>
    <div class="track"><div class="bar"></div></div>
  </div>
</div>
</div>

<script>
(function(){
  // Show only once per browser session (first visit until tab closed)
  var splash = document.getElementById('av-splash');
  // Detect if launched as an installed app (PWA standalone mode)
  var isApp = window.matchMedia('(display-mode: standalone)').matches
              || window.navigator.standalone === true;
  if (!isApp) {
    // Normal browser tab: show only once per session
    if (sessionStorage.getItem('avSplashSeen')) {
      document.documentElement.classList.remove('av-loading');
      splash.parentNode.removeChild(splash);
      return;
    }
  }
  // Installed app: splash plays on every launch
const colors=['#ff4d4d','#ff8a8a','#4d7dff','#8aa6ff','#ffffff'];
  const pc=document.getElementById('particles');
  for(let i=0;i<34;i++){
    const p=document.createElement('div');
    p.className='particle';
    const s=2+Math.random()*4;
    p.style.left=Math.random()*100+'vw';
    p.style.bottom='-10px';
    p.style.width=p.style.height=s+'px';
    const c=colors[Math.floor(Math.random()*colors.length)];
    p.style.background=c;
    p.style.boxShadow='0 0 '+(s*2)+'px '+c;
    p.style.animationDuration=(5+Math.random()*7)+'s';
    p.style.animationDelay=(Math.random()*7)+'s';
    pc.appendChild(p);
  }
  const pct=document.getElementById('pct');
  const ms=[0,14,36,60,84,100], t=[0,540,1080,1740,2400,3000];
  ms.forEach((target,i)=>{
    setTimeout(()=>{
      const start=ms[i-1]||0, dur=i>0?t[i]-t[i-1]:1, st=performance.now();
      (function tick(now){
        const pr=Math.min((now-st)/dur,1);
        pct.textContent=Math.round(start+(target-start)*pr)+'%';
        if(pr<1)requestAnimationFrame(tick);
      })(st);
    },2300+t[i]);
  });

  // Hide after the animation finishes, then reveal the site
  setTimeout(function(){
    splash.classList.add('av-hide');
    document.documentElement.classList.remove('av-loading');
    setTimeout(function(){
      if (splash.parentNode) splash.parentNode.removeChild(splash);
    }, 750);
    sessionStorage.setItem('avSplashSeen','1');
  }, 5600);
})();
</script>
